import sys; sys.path.insert(0, "/home/claude/winesite/scripts/na")
from na_lib import ava, site, region, save_part
SRC = [("TTB: Established American Viticultural Areas", "https://www.ttb.gov/wine/established-avas"),
       ("UC Davis Library AVA Digitizing Project", "https://github.com/UCDavisLibrary/ava"),
       ("Federal Register, Comptche final rule (2024)", "https://www.federalregister.gov/documents/2024/04/08/2024-07395/establishment-of-the-comptche-viticultural-area"),
       ("Federal Register, Long Valley-Lake County final rule (2023)", "https://www.federalregister.gov/documents/2023/07/05/2023-14119"),
       ("Federal Register, proposed renaming of Mendocino Ridge (2024)", "https://www.federalregister.gov/documents/2024/01/05/2024-00057/proposed-renaming-of-the-mendocino-ridge-viticultural-area")]
M, L, N = "Mendocino County", "Lake County", "North Coast"
regions = [
 region("us", M, 39.15, -123.30, 8.6,
 "Redwoods, fog and old Italian vines: California's northernmost serious wine county, and a pioneer of organic farming.",
 "Mendocino County has around 16,000 to 17,000 acres of vines split between two different worlds. The cool Anderson Valley and the coastal ridges feel the Pacific and grow Pinot Noir, Chardonnay, Gewürztraminer and sparkling wine. Inland, the warm Ukiah, Redwood and Potter valleys along the upper Russian River grow Zinfandel, Petite Sirah, Carignan, Cabernet and Rhône varieties, much of it on old, dry-farmed vines planted by Italian families.\n\nMendocino has a higher share of certified organic and biodynamic vineyards than almost any US county, a legacy of Fetzer's organic commitment in the 1980s and of the county's back-to-the-land culture.",
 "Gold Rush-era farmers planted vines in the 1850s, and Italian immigrants built the inland industry around Ukiah and Redwood Valley before Prohibition. Parducci (1932) was the county's first post-Prohibition winery. Barney Fetzer founded Fetzer in Redwood Valley in 1968, and Roederer Estate brought Champagne investment to the Anderson Valley in 1982. In 2004 Mendocino became the first US county to ban the growing of genetically modified organisms.",
 "Coastal hills of Franciscan sandstone and redwood forest; the Anderson Valley channels fog inland from the Navarro River mouth. Inland valleys have deep alluvial soils and hot summers. Mendocino Ridge vineyards sit above the fog on isolated ridgetops.",
 "Pinot Noir, Chardonnay, Gewürztraminer and Riesling in the Anderson Valley; Zinfandel, Petite Sirah, Carignan, Cabernet Sauvignon, Syrah, Sauvignon Blanc inland.",
 "Traditional-method sparkling wine; lean, aromatic Pinot Noir; Alsace-style whites; old-vine Zinfandel and Carignan.",
 "Mendocino AVA covers the main valleys; 'Mendocino County' is also a legal county appellation. Sub-AVAs are listed below.",
 ["Mendocino", "Anderson Valley", "Mendocino Ridge", "Yorkville Highlands", "Redwood Valley", "Potter Valley", "McDowell Valley", "Cole Ranch", "Covelo", "Dos Rios", "Eagle Peak Mendocino County", "Comptche"], SRC, parent="California"),
 region("us", L, 38.95, -122.80, 8.8,
 "High-elevation volcanic country around California's largest natural lake.",
 "Lake County sits over the Mayacamas from Napa and Sonoma, around Clear Lake, the largest natural freshwater lake wholly within California. Vineyards are high, mostly from 400 to more than 800 m, under bright sun with cold nights, and many grow in red, obsidian-studded volcanic soils from Mount Konocti and the Clear Lake volcanic field. Sauvignon Blanc and Cabernet Sauvignon are the stars, and Napa wineries buy a great deal of Lake County fruit.",
 "Before Prohibition Lake County had more than 30 wineries. The English actress Lillie Langtry bought land in Guenoc Valley in 1888 and planned to make wine there. After Prohibition the vines were mostly pulled for walnuts and pears, and the replanting came from the 1960s onward.",
 "Volcanic soils, high elevation and clean air give intense UV and large day-night temperature swings. Clear Lake moderates temperatures near its shores.",
 "Sauvignon Blanc, Cabernet Sauvignon, Petite Sirah, Zinfandel, Merlot, Syrah.",
 "Crisp, grassy Sauvignon Blanc and firm, dark Cabernet at good prices.",
 "Clear Lake is the umbrella AVA around the lake; several smaller AVAs sit within it.",
 ["Clear Lake", "Red Hills Lake County", "Big Valley District-Lake County", "Kelsey Bench-Lake County", "High Valley", "Upper Lake Valley", "Long Valley-Lake County", "Guenoc Valley", "Benmore Valley"], SRC, parent="California")]

A = []
A.append(ava("Mendocino", M, "The main AVA (1984) for the southern and central valleys of Mendocino County, including Anderson, Ukiah, Redwood and Potter valleys and McDowell Valley. It is used for blends from across those valleys; inland it means warm-climate Zinfandel, Petite Sirah, Carignan and Cabernet.", sub="North Coast", styles=["red", "white"], dom="red", grapes="Zinfandel, Petite Sirah, Carignan, Cabernet Sauvignon, Chardonnay, Sauvignon Blanc", producers=["Parducci", "Fetzer", "Bonterra", "McNab Ridge"]))
A.append(ava("Anderson Valley", M,
 "A narrow, 25 km valley (1983) along the Navarro River that opens toward the Pacific, so fog and cool air pour in every evening. It is one of California's coolest wine valleys and its most Alsatian: Gewürztraminer, Riesling and Pinot Gris grow beside Pinot Noir and Chardonnay, and the valley hosts an annual Alsace festival.\n\nRoederer Estate arrived from Champagne in 1982 and showed that the valley could make world-class sparkling wine; its L'Ermitage is a benchmark. Pinot Noir from the 'deep end' near Philo and Navarro is tense, floral and savoury.",
 sub="Mendocino", styles=["red", "white", "sparkling"], dom="red", grapes="Pinot Noir, Chardonnay, Gewürztraminer, Riesling, Pinot Gris",
 terroir="Marine sedimentary soils on benches and slopes; fog and large daily temperature swings.",
 producers=["Roederer Estate", "Navarro Vineyards", "Husch", "Goldeneye", "Littorai (sourcing)", "Handley", "Drew", "Lazy Creek"],
 nerd="The valley had its own jargon, Boontling, invented by Boonville residents around 1900; a 'horn of Bahl' is a glass of good wine."))
A.append(ava("Mendocino Ridge", M,
 "The only non-contiguous AVA in the United States (1997): it consists of every piece of land above 1,200 feet (366 m) in a coastal strip of southwestern Mendocino County, so its map looks like an archipelago of 'islands in the sky' poking above the marine layer. Old Zinfandel vineyards such as Zeni and Ciapusci, planted by Italian families, grow on these ridges alongside newer Pinot Noir.\n\nIn January 2024 TTB proposed renaming it 'Mendocino Coast Ridge' to stress its coastal identity; as of late 2026 that proposal had not been finalised.",
 sub="Mendocino", styles=["red"], dom="red", grapes="Zinfandel, Pinot Noir, Syrah",
 producers=["Edmeades (Zeni Vineyard)", "Greenwood Ridge", "Drew", "Mariah"],
 nerd="Because only land above 1,200 feet counts, the AVA covers about 87,000 acres on paper but has only a few hundred acres of vines."))
A.append(ava("Yorkville Highlands", M, "Rolling, rocky hills (1998) along Highway 128 between Cloverdale and the Anderson Valley, at about 300 to 760 m. Gravelly, low-fertility soils and a climate between the warm Alexander Valley and the cool Anderson Valley suit Sauvignon Blanc, Pinot Noir and Bordeaux and Rhône reds.", sub="Mendocino", styles=["red", "white"], dom="red", grapes="Sauvignon Blanc, Pinot Noir, Cabernet Sauvignon, Syrah", producers=["Yorkville Cellars", "Maple Creek"]))
A.append(ava("Redwood Valley", M, "A warm valley (1997) north of Ukiah, at the head of the Russian River watershed, with red, iron-rich soils. Italian families planted Zinfandel, Carignan and Petite Sirah here early in the 20th century, and Fetzer was founded here in 1968. Old vines still give some of Mendocino's best Zinfandel and Carignan.", sub="Mendocino", styles=["red", "white"], dom="red", grapes="Zinfandel, Carignan, Petite Sirah, Cabernet Sauvignon", producers=["Fetzer (origins)", "Frey", "Barra", "Golden Vineyards"]))
A.append(ava("Potter Valley", M, "A high, cool valley (1983) northeast of Ukiah, ringed by mountains and fed by water diverted from the Eel River into the Russian River. Cold nights and a long season favour aromatic whites (Riesling, Sauvignon Blanc) and botrytised dessert wines, as well as Pinot Noir.", sub="Mendocino", styles=["white", "red", "sweet"], dom="white", grapes="Sauvignon Blanc, Riesling, Pinot Noir, Chardonnay"))
A.append(ava("McDowell Valley", M, "A tiny bench valley (1982) east of Hopland at around 300 m. It is best known for old Syrah and Grenache, among California's oldest Rhône plantings (some vines date from 1919), which McDowell Valley Vineyards bottled in the early days of the Rhône Rangers movement.", sub="Mendocino", styles=["red", "rose"], dom="red", grapes="Syrah, Grenache, Petite Sirah", producers=["McDowell Valley Vineyards"]))
A.append(ava("Cole Ranch", M, "Once the smallest AVA in the United States (1983) at about 150 to 190 acres, a single ranch in a narrow valley in the hills between Ukiah and Boonville, owned by the Cole family. It grows Riesling, Cabernet Sauvignon and Merlot. Hawaii's Ulupalakua (2021) has since taken the 'smallest AVA' title.", sub="Mendocino", styles=["white", "red"], dom="red", grapes="Cabernet Sauvignon, Merlot, Riesling, Chardonnay", nerd="Cole Ranch is essentially a one-owner AVA, which is legal as long as the petition proves the area is geographically distinct."))
A.append(ava("Covelo", M, "A remote, high valley (2006) of about 38,000 acres in northeastern Mendocino County, at about 425 m, surrounded by mountains and the Round Valley Indian Reservation. Cold winters and warm summers; plantings are very small.", sub="Mendocino", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Zinfandel, Chardonnay"))
A.append(ava("Dos Rios", M, "A tiny, remote AVA (2005) of about 15,500 acres where the Middle Fork and main stem of the Eel River meet ('two rivers'), in rugged northern Mendocino County. It has only a few acres of vines.", sub="Mendocino", styles=["red"], dom="red", grapes="Zinfandel, Syrah, Cabernet Sauvignon"))
A.append(ava("Eagle Peak Mendocino County", M, "A mountainous AVA (2014) of about 26,260 acres northwest of Redwood Valley, with about 120 acres in 16 vineyards at the time of approval. The petition cited a marine-influenced climate, strong breezes, steep slopes and shallow soils with little water-holding capacity, which keep yields low for Pinot Noir and Rhône varieties.", sub="Mendocino", styles=["red", "white"], dom="red", grapes="Pinot Noir, Syrah, Merlot"))
A.append(ava("Comptche", M, "A small AVA (2024) of about 1,422 acres around the hamlet of Comptche, a few kilometres inland from Mendocino town. Unusually, TTB excluded it from the North Coast AVA because its foggy, cold, coastal climate and soils differ so sharply from the larger area. It grows Pinot Noir, Chardonnay and sparkling-wine grapes on a handful of small vineyards.", sub="Mendocino County coast", styles=["red", "white", "sparkling"], dom="red", grapes="Pinot Noir, Chardonnay, Sauvignon Blanc", nerd="Comptche is one of very few AVAs that is surrounded by, but not part of, a larger AVA."))

A.append(ava("Clear Lake", L, "The large umbrella AVA (1984) around Clear Lake, covering most of Lake County's vineyards. The lake moderates temperatures, while altitudes of 400 m and more give cool nights. Sauvignon Blanc and Cabernet Sauvignon lead, with Petite Sirah and Zinfandel from older plantings.", sub="North Coast", styles=["red", "white"], dom="red", grapes="Sauvignon Blanc, Cabernet Sauvignon, Petite Sirah, Zinfandel, Merlot", producers=["Steele", "Shannon Ridge", "Brassfield", "Six Sigma"], contains=["Red Hills Lake County", "Big Valley District-Lake County", "Kelsey Bench-Lake County", "High Valley", "Upper Lake Valley"]))
A.append(ava("Red Hills Lake County", L, "Volcanic hills (2004, expanded 2024) on the flanks of Mount Konocti south of Clear Lake, at about 430 to 900 m. The red soils are full of obsidian and the light is intense, so Cabernet Sauvignon develops thick skins, dark colour and firm tannin, often with surprising freshness. Andy Beckstoffer's Amber Knolls and Obsidian Ridge are among its best-known vineyards.", sub="Clear Lake", styles=["red"], dom="red", grapes="Cabernet Sauvignon, Merlot, Syrah, Petite Sirah", producers=["Obsidian Ridge", "Beckstoffer (Amber Knolls)", "Brassfield", "Shannon Ridge"], nerd="The 2004 petition reported about 3,100 acres of vineyards; obsidian chips glitter in the soil after rain."))
A.append(ava("Big Valley District-Lake County", L, "A flat basin (2013) on the southwest shore of Clear Lake around Kelseyville, with about 1,800 acres of vines at approval. High water tables and cold-air pooling give a cooler, frostier site than the surrounding hills; Sauvignon Blanc is the signature.", sub="Clear Lake", styles=["white", "red"], dom="white", grapes="Sauvignon Blanc, Cabernet Sauvignon, Zinfandel"))
A.append(ava("Kelsey Bench-Lake County", L, "A gently sloping bench (2013) between Big Valley and the Red Hills, at about 410 to 610 m, with about 900 acres of vines at approval. Better air drainage than Big Valley and deep, well-drained alluvial soils suit Cabernet Sauvignon, Petite Sirah and Sauvignon Blanc.", sub="Clear Lake", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Petite Sirah, Sauvignon Blanc"))
A.append(ava("High Valley", L, "A narrow, east-west valley (2005) in northeastern Lake County above Clear Lake, at about 500 to 920 m. Cool air drains down from the surrounding ridges, giving a long season for Sauvignon Blanc, Cabernet and Syrah. Its boundary was trimmed in 2023 when the neighbouring Long Valley-Lake County AVA was created.", sub="Clear Lake", styles=["red", "white"], dom="red", grapes="Sauvignon Blanc, Cabernet Sauvignon, Syrah", producers=["Brassfield"]))
A.append(ava("Upper Lake Valley", L, "A valley (2022) at the north end of Clear Lake around the town of Upper Lake, about 17,360 acres. The petition stressed hydrogeology: a shallow water table fed by streams from the Mendocino National Forest, plus soils and a climate that differ from the rest of Clear Lake. Sauvignon Blanc and Cabernet Sauvignon dominate.", sub="Clear Lake", styles=["white", "red"], dom="white", grapes="Sauvignon Blanc, Cabernet Sauvignon"))
A.append(ava("Long Valley-Lake County", L, "A small, high valley (2023) of about 7,605 acres in northeastern Lake County, northeast of Clear Lake, with five vineyards (about 149 acres) and three wineries at approval. Elevation and cold winters distinguish it from High Valley, part of which it took over. Unusually, it lies outside the Clear Lake AVA; TTB adjusted the North Coast boundary to include it.", sub="North Coast", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Sauvignon Blanc, Petite Sirah"))
A.append(ava("Guenoc Valley", L, "An early single-proprietor AVA (1981) in southern Lake County, on the old Guenoc Ranch. The English actress Lillie Langtry, a friend of the future Edward VII, bought the ranch in 1888 and hired a Bordeaux winemaker; her portrait was later used on the labels of Langtry Estate. Warm and dry, it grows Petite Sirah, Cabernet Sauvignon and Sauvignon Blanc.", sub="North Coast", styles=["red", "white"], dom="red", grapes="Petite Sirah, Cabernet Sauvignon, Sauvignon Blanc", producers=["Langtry Farms"]))
A.append(ava("Benmore Valley", L, "A small, high valley (1991) in the Mayacamas on the western edge of Lake County, at about 730 m. Once planted mainly to Chardonnay for large brands, it now has few vines.", sub="North Coast", styles=["white"], dom="white", grapes="Chardonnay"))

A.append(ava("Solano County Green Valley", N, "A small valley (1983) in the hills of western Solano County, next door to Napa's Wild Horse Valley and east of Coombsville, cooled by air from San Pablo Bay through the Carquinez Strait. Merlot, Cabernet Sauvignon and Chardonnay grow on gentle slopes. It was renamed in its current form to distinguish it from Sonoma's Green Valley.", sub="North Coast", styles=["red", "white"], dom="red", grapes="Merlot, Cabernet Sauvignon, Chardonnay"))
A.append(ava("Suisun Valley", N, "A valley (1982) just east of Napa across the Vaca Range near Fairfield, among the first AVAs approved in California. Afternoon winds from the Suisun Bay cool it, and it grows Petite Sirah, Cabernet Sauvignon and Zinfandel. Wooden Valley and Ledgewood Creek are among its wineries.", sub="North Coast", styles=["red", "white"], dom="red", grapes="Petite Sirah, Cabernet Sauvignon, Zinfandel, Chardonnay", producers=["Wooden Valley", "Ledgewood Creek", "Sunset Cellars"]))
A.append(ava("Capay Valley", "Sacramento Valley", "A long valley (2002) in western Yolo County along Cache Creek, between the Blue Ridge and the Capay Hills. Warm and dry, it grows Rhône and Mediterranean varieties on a small scale, and the area is known more widely for organic farms.", sub="Yolo County", styles=["red"], dom="red", grapes="Syrah, Tempranillo, Grenache"))
A.append(ava("Dunnigan Hills", "Sacramento Valley", "Rolling hills (1993) in northern Yolo County beside Interstate 5, created at the request of R.H. Phillips, which planted large vineyards here in the 1980s. Warm days and Delta breezes; Syrah, Viognier and Chardonnay.", sub="Yolo County", styles=["red", "white"], dom="red", grapes="Syrah, Viognier, Chardonnay, Cabernet Sauvignon", producers=["R.H. Phillips (EXP)"]))
A.append(ava("Winters Highlands", "Sacramento Valley", "A small upland AVA (2023) of about 7,300 acres in the foothills west of Winters, straddling Yolo and Solano counties near the Napa line. The petition cited higher humidity and less rainfall than surrounding areas, plus distinctive soils; vineyards grow Bordeaux and Mediterranean varieties.", sub="Yolo and Solano counties", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Petite Sirah, Tempranillo"))
A.append(ava("Clarksburg", "Sacramento Valley", "Delta country (1984, expanded 2022) south of Sacramento, where vineyards grow on reclaimed river islands behind levees. Cool afternoon breezes through the Carquinez Strait make it cooler than Lodi. Chenin Blanc is the historic speciality, plus Petite Sirah and Albariño; much fruit is sold to wineries elsewhere.", sub="Sacramento-San Joaquin Delta", styles=["white", "red"], dom="white", grapes="Chenin Blanc, Petite Sirah, Chardonnay, Albariño", producers=["Bogle", "Dry Creek Vineyard (Clarksburg Chenin)", "Heringer"], contains=["Merritt Island"]))
A.append(ava("Merritt Island", "Sacramento Valley", "A Delta island (1983) of about 5,000 acres inside Clarksburg, bounded by the Sacramento River and Elk Slough. Sandy loam over peat and cool Delta breezes; the Bogle family petitioned for it.", sub="Clarksburg", styles=["red", "white"], dom="red", grapes="Petite Sirah, Chenin Blanc, Chardonnay", producers=["Bogle"]))
A.append(ava("Willow Creek", "Far North California", "A small AVA (1983) along the Trinity River in eastern Humboldt and western Trinity counties, where coastal fog meets inland heat. A handful of growers make Zinfandel and Pinot Noir.", sub="Humboldt and Trinity counties", styles=["red"], dom="red", grapes="Zinfandel, Pinot Noir, Cabernet Sauvignon"))
A.append(ava("Trinity Lakes", "Far North California", "A remote mountain AVA (2005) of about 96,000 acres around Lewiston and Trinity Lake in Trinity County, high in the Klamath Mountains. Vines are few and the climate is cool and continental.", sub="Trinity County", styles=["red"], dom="red", grapes="Pinot Noir, Merlot"))
A.append(ava("Seiad Valley", "Far North California", "One of California's northernmost AVAs (1994), a tiny valley on the Klamath River in Siskiyou County near the Oregon border. It was established for a single grower and has almost no commercial vineyards today.", sub="Siskiyou County", styles=["red"], dom="red", grapes="Pinot Noir, Cabernet Sauvignon"))
A.append(ava("Inwood Valley", "Far North California", "A small valley (2012) of about 28,400 acres in eastern Shasta County, in the foothills of the southern Cascades east of Redding. At approval it had about 60 acres of vines; volcanic soils and cool nights from the Cascades suit Bordeaux and Rhône varieties.", sub="Shasta County", styles=["red"], dom="red", grapes="Cabernet Sauvignon, Syrah, Merlot"))
A.append(ava("Manton Valley", "Far North California", "A small valley (2014) of about 11,200 acres on the western slope of Mount Lassen in Shasta and Tehama counties. Volcanic soils from Lassen and elevations around 600 m give cool nights; a few small wineries.", sub="Shasta and Tehama counties", styles=["red", "white"], dom="red", grapes="Syrah, Cabernet Sauvignon, Petite Sirah"))

S = []
